package com.hmdp.ai.infrastructure.sandbox;
import org.springframework.stereotype.Component;import java.nio.charset.StandardCharsets;import java.nio.file.*;
@Component public class SandboxFileService {public Path resolve(Path workspace,String relative){if(relative==null||relative.isEmpty())throw new IllegalArgumentException("SANDBOX_FILE_NAME_REQUIRED");Path target=workspace.resolve(relative).normalize();if(!target.startsWith(workspace)||relative.contains(".."))throw new IllegalArgumentException("SANDBOX_PATH_TRAVERSAL");return target;}public void write(Path workspace,String relative,String content,int maxBytes){try{byte[]bytes=content.getBytes(StandardCharsets.UTF_8);if(bytes.length>maxBytes)throw new IllegalArgumentException("SANDBOX_INPUT_TOO_LARGE");Path target=resolve(workspace,relative);Files.createDirectories(target.getParent());Files.write(target,bytes,StandardOpenOption.CREATE_NEW);}catch(IllegalArgumentException e){throw e;}catch(Exception e){throw new IllegalStateException("SANDBOX_FILE_WRITE_FAILED",e);}}}
